e } = await itemRef.replace\u003cItemDocument\u003e(replacement);\r\n  assertStatus(replaceStatusCode, [200], \"Replace item\");\r\n  console.log(\"Replaced item:\", replacedItem);\r\n\r\n  const { statusCode: deleteStatusCode } = await itemRef.delete();\r\n  assertStatus(deleteStatusCode, [204], \"Delete item\");\r\n  console.log(\"Deleted item successfully.\");\r\n}\r\n\r\nmain().catch((error: unknown) =\u003e {\r\n  if (isCosmosError(error)) {\r\n    console.error(`Cosmos DB error (${error.code}): ${describeCosmosError(error)}`);\r\n    process.exitCode = 1;\r\n    return;\r\n  }\r\n\r\n  if (error instanceof Error) {\r\n    console.error(`Unexpected error: ${error.message}`);\r\n    process.exitCode = 1;\r\n    return;\r\n  }\r\n\r\n  console.error(\"Unexpected non-error exception thrown.\");\r\n  process.exitCode = 1;\r\n});\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  // Visit https://aka.ms/tsconfig to read more about this file\r\n  \"compilerOptions\": {\r\n    \"rootDir\": \"src\",\r\n    \"outDir\": \"dist\",\r\n    \"module\": \"commonjs\",\r\n    \"target\": \"es2022\",\r\n    \"types\": [\"node\"],\r\n    \"sourceMap\": true,\r\n    \"declaration\": true,\r\n    \"declarationMap\": true,\r\n    \"noUncheckedIndexedAccess\": true,\r\n    \"exactOptionalPropertyTypes\": true,\r\n    \"strict\": true,\r\n    \"isolatedModules\": true,\r\n    \"moduleDetection\": \"force\",\r\n    \"skipLibCheck\": true,\r\n    \"esModuleInterop\": true,\r\n    \"resolveJsonModule\": true\r\n  }\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.g., attempt to build the code, check package versions):\r\n\r\n1. **Code Builds** — Does the generated code compile/build without errors? If you have build tools avail